import React, { useEffect, useState } from "react";
import axios from "axios";

const ViewApplications = () => {
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);

  const [editRowId, setEditRowId] = useState(null);
  const [formData, setFormData] = useState({
    reason: "",
    status: "",
  });

  useEffect(() => {
    fetchApplications();
  }, []);

  const fetchApplications = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(
        "http://127.0.0.1:8000/VJISS/view_applications",
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      setApplications(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (app) => {
    setEditRowId(app.application_id);
    setFormData({
      reason: app.reason || "",
      status: app.status || "Pending",
    });
  };

  const handleSave = async (id) => {
    try {
      const token = localStorage.getItem("token");

      await axios.put(
        `http://127.0.0.1:8000/VJISS/update_application/${id}`,
        formData,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      alert("Application updated successfully");
      setEditRowId(null);
      fetchApplications();
    } catch (error) {
      console.error("Update failed:", error);
      alert("Failed to update application");
    }
  };

  if (loading) return <p className="p-6">Loading...</p>;

  return (
    <div className="p-6">
      <h2 className="text-2xl font-bold mb-4">Applications</h2>

      <div className="overflow-x-auto">
        <table className="min-w-full border border-gray-300">
          <thead className="bg-gray-100">
            <tr>
              <th className="border p-2">ID</th>
              <th className="border p-2">Name</th>
              <th className="border p-2">Internship</th>
              <th className="border p-2">Reason</th>
              <th className="border p-2">Status</th>
              <th className="border p-2">Applied On</th>
              <th className="border p-2">Action</th>
            </tr>
          </thead>

          <tbody>
            {applications.map((app) => (
              <tr key={app.application_id}>
                <td className="border p-2">{app.application_id}</td>

                <td className="border p-2">
                  {app.first_name} {app.last_name}
                </td>

                <td className="border p-2">
                  {app.internship_offers?.internship_name || "—"}
                </td>

                {/* Reason */}
                <td className="border p-2">
                  {editRowId === app.application_id ? (
                    <textarea
                      className="w-full border rounded p-1"
                      value={formData.reason}
                      onChange={(e) =>
                        setFormData({ ...formData, reason: e.target.value })
                      }
                    />
                  ) : (
                    app.reason || "—"
                  )}
                </td>

                {/* Status */}
                <td className="border p-2">
                  {editRowId === app.application_id ? (
                    <select
                      className="border rounded p-1"
                      value={formData.status}
                      onChange={(e) =>
                        setFormData({ ...formData, status: e.target.value })
                      }
                    >
                      <option value="Pending">Pending</option>
                      <option value="Approved">Approved</option>
                      <option value="Rejected">Rejected</option>
                    </select>
                  ) : (
                    <span
                      className={`font-semibold ${
                        app.status === "Approved"
                          ? "text-green-600"
                          : app.status === "Rejected"
                          ? "text-red-600"
                          : "text-yellow-600"
                      }`}
                    >
                      {app.status || "Pending"}
                    </span>
                  )}
                </td>

                <td className="border p-2">
                  {new Date(app.applied_on).toLocaleDateString()}
                </td>

                {/* Actions */}
                <td className="border p-2">
                  {editRowId === app.application_id ? (
                    <button
                      onClick={() => handleSave(app.application_id)}
                      className="px-3 py-1 bg-green-600 text-white rounded"
                    >
                      Save
                    </button>
                  ) : (
                    <button
                      onClick={() => handleEdit(app)}
                      className="px-3 py-1 bg-yellow-500 text-white rounded"
                    >
                      Edit
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ViewApplications;
